function loadModule(path, requireFn, mocks) {
    var code = file_read({ path: path });
    if (!code || !code.trim()) {
        throw new Error('loadModule: cannot read file: ' + path);
    }

    // Build preamble that shadows dmtools globals with our mocks
    var _testMocks_ = mocks || {};
