        // three-dot semantics as the diff, against freshly fetched refs.
        var calls = [];
        var writes = [];
        var responses = {};
        responses['git ls-remote --heads origin ai/PROJ-7'] = '9a7e2aec9a7e2aec9a7e2aec9a7e2aec9a7e2aec\trefs/heads/ai/PROJ-7';
