        assert.ok(out.indexOf('**Branch**') !== -1);
        assert.ok(out.indexOf('**Pull Request**') !== -1);
        assert.equal(out.indexOf('h3.'), -1, 'no wiki heading');
        assert.equal(out.indexOf('{code'), -1, 'no wiki code tag');
