        assert.ok(out.indexOf('*Re-run result*: ❌ *FAILED*') !== -1);
        assert.ok(out.indexOf('*Pull Request*') === -1, 'no PR line when there is no PR');
        assert.ok(out.indexOf('still red') !== -1);
    });

});

