            'Script started on 2026-10-16\nCOMMAND=git status\nwarning: redirecting to https://git.example.com/\nOn branch main\nCOMMAND_EXIT_CODE=0\nScript done on 2026-10-16\n');
        assert.equal(out, 'On branch main');
    });

