    });

    test('AC3: warning + real ref line still classifies "exists" (both merge orders)', function() {
        var config = makeConfig();
        var configLoaderStub = makeConfigLoaderStub(
            { development: 'ai/PROJ-1', feature: 'release/rc_mobile_proj-1' },
