        var err = null;
        try { m.commitAndPush('PROJ-123', true, REWORK_CONFIG, false); } catch (e) { err = e; }

        assert.ok(err, 'a genuinely mismatched remote tip must still be caught');
        assert.contains(err.message, 'Push rejected',
