# Replace a local cleanCommandOutput copy with a delegate to prHelper.
# Usage: consolidate.pl <file> <requireLineToAdd|-> <helperVarName>
my ($file, $requireLine, $var) = @ARGV;
local $/; open my $fh, '<', $file or die "open $file: $!";
my $src = <$fh>; close $fh;
my $n = ($src =~ s/function cleanCommandOutput\(output\)\s*\{(?:[^{}]|\{[^{}]*\})*\}/\/\/ Canonical copy (gh-823\/gh-912): the warning:\/note: line filter lives in\n\/\/ common\/pullRequest.js once — this delegate keeps every local call site.\nfunction cleanCommandOutput(output) {\n    return $var.cleanCommandOutput(output);\n}/);
die "no cleanCommandOutput replaced in $file\n" unless $n == 1;
if ($requireLine ne '-') {
    die "require line already present in $file\n" if $src =~ /\Q$requireLine\E/;
    # insert after the first require line
    $src =~ s/^(var \w+ = require\([^\n]+\);)$/$1\n$requireLine/m
        or die "no require anchor in $file\n";
}
open my $out, '>', $file or die "write $file: $!";
print $out $src; close $out;
print "consolidated $file (+require: ", ($requireLine eq '-' ? 'no' : 'yes'), ")\n";
