test('chains existing preCliJSAction before checkout', function() {
    var calls = [];
    var chainedCalls = [];
    var mod = loadModule(
        'js/preCliSnapshotSetup.js',
        makeRequire({
            './configLoader.js': makeConfigLoaderStub('develop/3.9.0'),
